using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static ReportingConfiguration _reporting = null!;

    [ClassInitialize]
    public static async Task ClassInit(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        _reporting = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_Responds_Relevantly()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await using var scenario = await _reporting.CreateScenarioRunAsync("Chat_Responds_Relevantly");

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
        };

        var chatTurn = new ChatTurn(messages, response);
        await scenario.EvaluateAsync(chatTurn, evaluators);

        // Verify minimum quality thresholds
        var results = scenario.GetResults();
        foreach (var result in results)
        {
            Assert.IsTrue(
                result.Value.Rating >= EvaluationRating.Good,
                $"Evaluator '{result.Key}' rated response as '{result.Value.Rating}' which is below the 'Good' threshold.");
        }
    }

    [TestMethod]
    public async Task Chat_Handles_MultiTurn_Conversation()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Remember that my favorite color is blue."),
        };

        var firstResponse = await chatClient.GetResponseAsync(messages);
        messages.Add(new ChatMessage(ChatRole.Assistant, firstResponse.Text));
        messages.Add(new ChatMessage(ChatRole.User, "What is my favorite color?"));

        var secondResponse = await chatClient.GetResponseAsync(messages);

        await using var scenario = await _reporting.CreateScenarioRunAsync("Chat_Handles_MultiTurn_Conversation");

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
        };

        var chatTurn = new ChatTurn(messages, secondResponse);
        await scenario.EvaluateAsync(chatTurn, evaluators);

        Assert.IsTrue(
            secondResponse.Text?.Contains("blue", StringComparison.OrdinalIgnoreCase) == true,
            "The agent should recall context from earlier in the conversation.");
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var storageOptions = new DiskBasedReportingConfiguration.Options
        {
            StorageRootPath = Path.Combine(
                Path.GetTempPath(),
                "MyApp.Evaluation",
                "reports"),
        };

        return DiskBasedReportingConfiguration.Create(storageOptions);
    }
}

